begin;
alter table hq.compliance_risks add column if not exists evidence_reference text;
update hq.compliance_risks set owner_employee_id='40000000-0000-0000-0000-000000000001' where owner_employee_id is null;
update hq.compliance_risks set target_date=current_date+30 where target_date is null;
update hq.compliance_risks set evidence_reference='legacy-risk-evidence-pending' where evidence_reference is null;
alter table hq.compliance_risks alter column owner_employee_id set not null,alter column target_date set not null,alter column evidence_reference set not null;
create table if not exists hq.compliance_risk_evidence(id uuid primary key default gen_random_uuid(),risk_id uuid not null references hq.compliance_risks(id) on delete cascade,evidence_type text not null,title text not null,reference text not null,uploaded_by uuid not null references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.compliance_checks(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),title text not null,scope text,check_type text not null,scheduled_on date,completed_on date,status text not null default 'planned' check(status in('planned','in_progress','passed','failed','remediation')),findings text,evidence_reference text,owner_employee_id uuid not null references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.compliance_alerts(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),risk_id uuid references hq.compliance_risks(id) on delete cascade,alert_type text not null,severity text not null check(severity in('info','warning','high','critical')),title text not null,status text not null default 'open' check(status in('open','acknowledged','resolved')),due_at timestamptz,created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists hq.business_continuity_plans(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),title text not null,critical_process text not null,recovery_objective text not null,recovery_time_hours integer not null check(recovery_time_hours>0),owner_employee_id uuid not null references hq.employees(id),last_tested_on date,next_test_on date,status text not null default 'draft' check(status in('draft','active','testing','needs_improvement','retired')),evidence_reference text,created_at timestamptz not null default now());
create table if not exists hq.compliance_measure_history(id uuid primary key default gen_random_uuid(),risk_id uuid references hq.compliance_risks(id) on delete cascade,incident_id uuid references hq.compliance_incidents(id) on delete cascade,measure_type text not null,description text not null,previous_state jsonb not null default '{}'::jsonb,new_state jsonb not null default '{}'::jsonb,actor_employee_id uuid references hq.employees(id),created_at timestamptz not null default now(),check(risk_id is not null or incident_id is not null));
create unique index if not exists uq_hq_open_risk_alert on hq.compliance_alerts(risk_id,alert_type) where status='open';
do $$ declare t text;begin foreach t in array array['compliance_risk_evidence','compliance_checks','compliance_alerts','business_continuity_plans','compliance_measure_history'] loop execute format('alter table hq.%I enable row level security',t);execute format('revoke all on hq.%I from public,anon,authenticated',t);execute format('grant all on hq.%I to service_role',t);end loop;end $$;
create or replace function hq.track_compliance_risk_change() returns trigger language plpgsql security definer set search_path=hq,public as $$ begin if old.status is distinct from new.status or old.mitigation_plan is distinct from new.mitigation_plan then insert into hq.compliance_measure_history(risk_id,measure_type,description,previous_state,new_state,actor_employee_id) values(new.id,'risk_update','Estado ou mitigação atualizados',jsonb_build_object('status',old.status,'mitigation_plan',old.mitigation_plan),jsonb_build_object('status',new.status,'mitigation_plan',new.mitigation_plan),new.owner_employee_id);end if;return new;end $$;
drop trigger if exists trg_hq_track_risk_measure on hq.compliance_risks;create trigger trg_hq_track_risk_measure after update on hq.compliance_risks for each row execute function hq.track_compliance_risk_change();
create or replace function hq.create_compliance_risk_alert() returns trigger language plpgsql security definer set search_path=hq,public as $$ begin if new.risk_score>=15 or new.target_date<current_date then insert into hq.compliance_alerts(legal_entity_id,platform_id,risk_id,alert_type,severity,title,due_at) values(new.legal_entity_id,new.platform_id,new.id,case when new.target_date<current_date then 'overdue' else 'high_risk' end,case when new.risk_score>=20 then 'critical' else 'high' end,'Risco requer atenção: '||new.title,new.target_date::timestamptz) on conflict do nothing;end if;return new;end $$;
drop trigger if exists trg_hq_risk_alert on hq.compliance_risks;create trigger trg_hq_risk_alert after insert or update of likelihood,impact,target_date,status on hq.compliance_risks for each row when(new.status<>'closed') execute function hq.create_compliance_risk_alert();
create index if not exists idx_hq_compliance_alerts on hq.compliance_alerts(status,severity,created_at desc);create index if not exists idx_hq_compliance_history on hq.compliance_measure_history(risk_id,created_at desc);
commit;
